class Solution:
    def getKthCharacter(self, root: Optional['RopeTreeNode'], k: int) -> str:
        node = root
        while node.len > 0:
            leftLen = node.left.len if node.left else 0
            if k <= leftLen:
                node = node.left
            else:
                k -= leftLen
                node = node.right
        return node.val[k - 1]

